const UserBio: React.FC<{ user: User }> = ({ user }) => {
    return (
        <div className="user-bio">
            <h3>{user.displayName}</h3>
            <article dangerouslySetInnerHTML={{ __html: user.bioText }} />
            <footer dangerouslySetInnerHTML={{ __html: user.signature }} />
        </div>
    );
};
